#![warn(clippy::all, clippy::pedantic)]

#![deny(missing_docs)]

//! A library for searching a needle in a stream of chunks.

/// Represents a match found in the stream.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct LiteralMatch {
    /// The starting byte offset of the match relative to the beginning of the stream.
    pub offset: u64,
}

/// The result of a literal search operation.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct LiteralSearchResult {
    /// A collection of matches found.
    pub matches: Vec<LiteralMatch>,
    /// True if the number of matches found exceeds `max_matches` and more might exist.
    pub truncated: bool,
    /// Total number of bytes processed from the input iterator.
    pub bytes_scanned: u64,
}

/// Errors that can occur during a literal search.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum LiteralSearchError {
    /// The needle provided is empty.
    EmptyNeedle,
    /// The match limit requested is zero.
    ZeroMatchLimit,
    /// The cumulative byte offset exceeded the capacity of a `u64`.
    OffsetOverflow,
}

/// Searches for a needle in a stream of chunks, handling boundary overlaps.
///
/// Memory usage is bounded by O(needle.len() + max_matches).
#[must_use]
pub fn search_literal_chunks<'a, I>(chunks: I, needle: &[u8], max_matches: usize) -> Result<LiteralSearchResult, LiteralSearchError>
where
    I: IntoIterator<Item = &'a [u8]>
{
    if needle.is_empty() {
        return Err(LiteralSearchError::EmptyNeedle);
    }
    if max_matches == 0 {
        return Err(LiteralSearchError::ZeroMatchLimit);
    }

    let mut matches = Vec::new();
    let mut bytes_scanned: u64 = 0;
    let mut truncated = false;
    let needle_len = needle.len();

    // We maintain a buffer to store the suffix of the previous data needed to detect boundary matches.
    // The overlap buffer stores the last `needle_len - 1` bytes of the stream seen so far.
    let mut overlap_buffer: Vec<u8> = Vec::with_capacity(needle_len.saturating_sub(1));

    for chunk in chunks {
        let chunk_len = chunk.len() as u64;

        // Check for overflow before updating bytes_scanned.
        if let Some(next_total) = bytes_scanned.checked_add(chunk_len) {
            bytes_scanned = next_total;
        } else {
            return Err(LiteralSearchError::OffsetOverflow);
        }

        // To handle boundary matches, we logically treat the stream as `overlap_buffer` followed by `chunk`.
        // However, to avoid large allocations, we iterate through the chunk and check if a needle 
        // can start at some position in the overlap or current chunk.

        // The window of interest is: [last (needle_len - 1) bytes] + [current chunk].
        // Let's create a small sliding view for this chunk.
        let mut local_view = Vec::with_capacity(overlap_buffer.len() + chunk.len());
        local_view.extend_from_slice(&overlap_buffer);
        local_view.extend_from_slice(chunk);

        // We only want to check positions that *start* within the current 'virtual' window 
        // but are not entirely contained in the previous chunks.
        // Specifically, a match starting at index `p` is new if its start position falls
        // within the range [bytes_scanned - chunk_len - (needle_len - 1), bytes_scanned - chunk_len + chunk_len - 1].
